#!/usr/bin/env node
/**
 * build-agents-md — generate AGENTS.md from CLAUDE.md.
 *
 * CLAUDE.md is the single hand-edited source of truth for AI-agent guidance.
 * AGENTS.md is a generated mirror for agent runtimes that read that filename
 * (Codex, Cursor, and others). The body is byte-identical; only the top-level
 * `# <FILE>.md - AI Agent Guidance for OpenSIP CLI` heading is swapped, and a
 * "do not edit" banner is inserted so hand-edits land in CLAUDE.md instead.
 *
 * The shared MCP-first block between the `<!-- opensip:agent-guidance -->`
 * markers is still owned by `opensip init` (packages/cli/.../agent-guidance.ts),
 * which writes the SAME block into both files — so mirroring stays consistent.
 *
 * Usage:
 *   node scripts/build-agents-md.mjs           # write AGENTS.md
 *   node scripts/build-agents-md.mjs --check    # fail (exit 1) if out of sync
 */

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = dirname(dirname(fileURLToPath(import.meta.url)));
const SRC_PATH = join(REPO_ROOT, 'CLAUDE.md');
const OUT_PATH = join(REPO_ROOT, 'AGENTS.md');
const CHECK_ONLY = process.argv.slice(2).includes('--check');

const CANONICAL_H1 = '# CLAUDE.md - AI Agent Guidance for OpenSIP CLI';
const MIRROR_H1 = '# AGENTS.md - AI Agent Guidance for OpenSIP CLI';
const GENERATED_BANNER =
  '<!-- Generated by scripts/build-agents-md.mjs from CLAUDE.md — do not edit by hand.\n' +
  '     Edit CLAUDE.md, then run `pnpm agents:build`. CI enforces sync via `pnpm agents:check`. -->';

const log = (msg) => console.error(`[build-agents-md] ${msg}`);

/**
 * Produce the AGENTS.md mirror from CLAUDE.md source text.
 *
 * Fails loudly if CLAUDE.md's first line is not the expected canonical heading,
 * so a retitle of CLAUDE.md can never silently produce a wrong mirror.
 *
 * @param {string} claudeSource
 * @returns {string}
 */
export function renderAgentsMd(claudeSource) {
  const firstNewline = claudeSource.indexOf('\n');
  const firstLine = firstNewline === -1 ? claudeSource : claudeSource.slice(0, firstNewline);
  if (firstLine !== CANONICAL_H1) {
    throw new Error(
      `CLAUDE.md first line is not the expected heading.\n` +
        `  expected: ${CANONICAL_H1}\n` +
        `  actual:   ${firstLine}\n` +
        `Update CANONICAL_H1/MIRROR_H1 in scripts/build-agents-md.mjs if the title changed intentionally.`,
    );
  }
  const rest = firstNewline === -1 ? '' : claudeSource.slice(firstNewline);
  return `${MIRROR_H1}\n${GENERATED_BANNER}${rest}`;
}

function main() {
  const source = readFileSync(SRC_PATH, 'utf8');
  const next = renderAgentsMd(source);
  const current = existsSync(OUT_PATH) ? readFileSync(OUT_PATH, 'utf8') : null;

  if (CHECK_ONLY) {
    if (current === next) {
      log('AGENTS.md in sync with CLAUDE.md.');
      return;
    }
    log('stale: AGENTS.md differs from CLAUDE.md — run `pnpm agents:build`.');
    process.exit(1);
  }

  if (current === next) {
    log('AGENTS.md already in sync.');
    return;
  }
  writeFileSync(OUT_PATH, next, 'utf8');
  log('wrote AGENTS.md from CLAUDE.md.');
}

// Only run when executed as a script (not when imported by tests).
if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main();
}
